('www-budgetbytes-com-chili-cheese-beef-n-mac', 'One Pot Chili Mac', 'American', 'Budget Bytes', 'https://www.budgetbytes.com/chili-cheese-beef-n-mac/', 35, 6, 2, 1, 2, 6, 40, array['beef', 'pasta', 'cheddar', 'onion', 'garlic', 'tomatoes', 'broth']::text[], '{"title":"One Pot Chili Mac","cuisine":"American","source":"Budget Bytes","url":"https://www.budgetbytes.com/chili-cheese-beef-n-mac/","minutes":35,"servings":6,"key":["Ground beef","Macaroni","Cheddar","Onion","Garlic","Tomato sauce","Beef broth"],"minor":["Chili powder","Smoked paprika","Garlic powder","Oregano","Flour"],"amounts":{"Ground beef":"1 lb","Macaroni":"1/2 lb (about 2 cups)","Cheddar":"1 cup shredded","Onion":"1 yellow","Garlic":"2 cloves","Tomato sauce":"8 oz","Beef broth":"3 cups"},"steps":[["Dice the onion, mince the garlic, and soften both in oil over medium heat until translucent.",null],["Add the ground beef and cook it until fully browned.",null],["Sprinkle in the flour and spices and stir for about two minutes.",2],["Pour in tomato sauce and beef broth, add dry macaroni, and bring to a boil.",null],["Cover and simmer on medium-low until pasta is tender and liquid turns to a gravy.",10],["Stir in half the cheddar, top with the rest, cover and let it melt off the heat.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":471,"protein_g":25,"carbs_g":36,"fat_g":25},"video":"https://www.youtube.com/watch?v=d8AjTrttx28"}'::jsonb),
('www-budgetbytes-com-sloppy-joes', 'Easy Old Fashioned Sloppy Joes', 'American', 'Budget Bytes', 'https://www.budgetbytes.com/sloppy-joes/', 30, 5, 2, 2, 1, 6, 40, array['beef', 'onion', 'bell peppers', 'garlic', 'tomatoes', 'tomato paste', 'buns']::text[], '{"title":"Easy Old Fashioned Sloppy Joes","cuisine":"American","source":"Budget Bytes","url":"https://www.budgetbytes.com/sloppy-joes/","minutes":30,"servings":5,"key":["Ground beef","Onion","Bell peppers","Garlic","Tomato sauce","Tomato paste","Hamburger buns"],"minor":["Apple cider vinegar","Brown sugar","Dijon mustard","Chili powder","Worcestershire sauce"],"amounts":{"Ground beef":"1 lb","Onion":"1 yellow","Bell peppers":"1 green","Garlic":"2 cloves","Tomato sauce":"15 oz can","Tomato paste":"3 Tbsp","Hamburger buns":"5"},"steps":[["Dice the onion and green pepper and mince the garlic.",null],["Brown the beef in a skillet and pour off extra fat.",null],["Add the vegetables and garlic and cook until softened.",null],["Mix in tomato sauce, paste, vinegar, sugar, mustard, chili powder, Worcestershire and salt.",null],["Simmer until the sauce thickens.",5],["Toast the buns and spoon the meat sauce onto them.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":440,"protein_g":22,"carbs_g":36,"fat_g":23},"video":"https://www.youtube.com/watch?v=XyoVejJRmtM"}'::jsonb),
('www-recipetineats-com-chicken-pot-pie', 'Chicken Pot Pie', 'American', 'RecipeTin Eats', 'https://www.recipetineats.com/chicken-pot-pie/', 75, 4, 5, 3, 3, 7, 78, array['chicken', 'milk', 'onion', 'carrots', 'celery', 'butter', 'puff pastry']::text[], '{"title":"Chicken Pot Pie","cuisine":"American","source":"RecipeTin Eats","url":"https://www.recipetineats.com/chicken-pot-pie/","minutes":75,"servings":4,"key":["Chicken breast","Milk","Onion","Carrots","Celery","Butter","Puff pastry"],"minor":["Garlic","Thyme","White wine","Flour","Parmesan","Frozen peas","Egg","Chicken broth"],"amounts":{"Chicken breast":"600 g (or boneless thighs)","Milk":"2 cups","Onion":"1 large","Carrots":"2-3 large","Celery":"3 ribs","Butter":"50 g","Puff pastry":"2 sheets"},"steps":[["Gently poach the chicken in milk, broth and stock powder, then shred it and save the liquid.",15],["Melt butter and cook garlic and onion, then add thyme, carrot and celery.",5],["Splash in wine and let it mostly cook off.",2],["Stir in flour for a minute, then slowly whisk in poaching liquid, broth and parmesan.",1],["Return chicken with peas and simmer until thick, then chill the filling.",30],["Fill pots, cap with puff pastry, brush with egg and cut a small vent.",null],["Bake at 180°C / 350°F until the pastry is deep golden.",38]],"technique":5,"prep":3,"precision":3,"nutrition":{"calories":588,"protein_g":47,"carbs_g":36,"fat_g":26},"video":null}'::jsonb),
('www-budgetbytes-com-shrimp-and-grits', 'Shrimp and Grits', 'Southern', 'Budget Bytes', 'https://www.budgetbytes.com/shrimp-and-grits/', 35, 4, 3, 2, 3, 6, 51, array['shrimp', 'grit', 'broth', 'cheddar', 'butter', 'onion', 'milk']::text[], '{"title":"Shrimp and Grits","cuisine":"Southern","source":"Budget Bytes","url":"https://www.budgetbytes.com/shrimp-and-grits/","minutes":35,"servings":4,"key":["Frozen shrimp","Grits","Chicken broth","Cheddar","Butter","Onion","Milk"],"minor":["Cajun seasoning","Garlic","Flour","Hot sauce","Scallions"],"amounts":{"Frozen shrimp":"16 oz jumbo, thawed, peeled","Grits":"1 cup old-fashioned","Chicken broth":"3 cups (divided)","Cheddar":"1 cup grated","Butter":"2 Tbsp","Onion":"1/2","Milk":"1/4 cup"},"steps":[["Bring water and most of the broth to a boil, whisk in grits, and simmer until thick.",18],["Pat shrimp dry, toss with Cajun seasoning, and sear in hot oil about a minute per side.",3],["In the same pan, soften the onion, then add garlic and sprinkle with flour.",null],["Whisk in remaining broth, milk and hot sauce to make a quick pan sauce.",null],["Slide the shrimp back in just to heat through.",null],["Stir butter and cheddar into the grits, then top with shrimp, sauce and scallions.",null]],"technique":3,"prep":2,"precision":3,"nutrition":{"calories":468,"protein_g":28,"carbs_g":40,"fat_g":21},"video":null}'::jsonb),
('www-budgetbytes-com-chicken-and-dumplings', 'Homemade Chicken and Dumplings', 'Southern', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-and-dumplings/', 55, 6, 4, 3, 3, 7, 67, array['chicken', 'flour', 'butter', 'milk', 'broth', 'onion', 'carrots']::text[], '{"title":"Homemade Chicken and Dumplings","cuisine":"Southern","source":"Budget Bytes","url":"https://www.budgetbytes.com/chicken-and-dumplings/","minutes":55,"servings":6,"key":["Chicken thighs","Flour","Butter","Milk","Chicken broth","Onion","Carrots"],"minor":["Garlic","Celery","Parsley","Thyme","Rosemary","Sage","Baking powder","Garlic powder"],"amounts":{"Chicken thighs":"4 boneless skinless (about 1 lb)","Flour":"1/4 cup + 1 cup","Butter":"4 Tbsp + 2 Tbsp melted","Milk":"1 cup + 1/2 cup","Chicken broth":"2 cups","Onion":"1 yellow","Carrots":"2"},"steps":[["Brown the chicken thighs in a deep skillet, then set them aside.",null],["Cook onion and garlic, then add diced carrots and celery.",null],["Melt butter in the pan, stir in flour, and cook the roux briefly.",2],["Add herbs, broth and milk and simmer until the gravy thickens.",null],["Dice the chicken, return it to the gravy, and keep it at a simmer.",null],["Mix dumpling dry ingredients, then stir in milk and melted butter.",null],["Drop 2-Tbsp spoonfuls on top, cover, and simmer until puffed; chicken should hit 165°F.",15]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":369,"protein_g":20,"carbs_g":28,"fat_g":19},"video":"https://www.youtube.com/watch?v=ze4_calJyEQ"}'::jsonb),
('www-budgetbytes-com-jambalaya', 'Slow Cooker Jambalaya', 'Cajun', 'Budget Bytes', 'https://www.budgetbytes.com/jambalaya/', 285, 8, 1, 3, 2, 6, 61, array['sausage', 'rice', 'tomatoes', 'chicken', 'onion', 'bell peppers', 'celery']::text[], '{"title":"Slow Cooker Jambalaya","cuisine":"Cajun","source":"Budget Bytes","url":"https://www.budgetbytes.com/jambalaya/","minutes":285,"servings":8,"key":["Smoked sausage","Rice","Canned tomatoes","Chicken thighs","Onion","Bell peppers","Celery"],"minor":["Garlic","Oregano","Thyme","Smoked paprika","Cayenne","Parsley","Scallions","Chicken broth"],"amounts":{"Smoked sausage":"12-16 oz","Rice":"2 cups long-grain white, uncooked","Canned tomatoes":"28 oz can diced","Chicken thighs":"2 boneless skinless (optional)","Onion":"1 yellow","Bell peppers":"1 green","Celery":"3 ribs"},"steps":[["Finely dice celery, onion and bell pepper, mince garlic, and put them in the slow cooker.",null],["Layer sliced sausage, cubed chicken and the dried spices on top.",null],["Pour over the canned tomatoes and broth, add parsley, and stir.",null],["Cook on high.",240],["Stir in the rice, making sure it is submerged, and cook until it absorbs the liquid.",22],["Fluff gently and finish with sliced green onions.",null]],"technique":1,"prep":3,"precision":2,"nutrition":{"calories":348,"protein_g":15,"carbs_g":41,"fat_g":13},"video":null}'::jsonb),
('www-budgetbytes-com-louisiana-red-beans-rice', 'Louisiana Style Red Beans and Rice with Sausage', 'Cajun', 'Budget Bytes', 'https://www.budgetbytes.com/louisiana-red-beans-rice/', 615, 6, 4, 3, 2, 7, 81, array['kidney beans', 'sausage', 'rice', 'onion', 'bell peppers', 'celery', 'garlic']::text[], '{"title":"Louisiana Style Red Beans and Rice with Sausage","cuisine":"Cajun","source":"Budget Bytes","url":"https://www.budgetbytes.com/louisiana-red-beans-rice/","minutes":615,"servings":6,"key":["Dry red beans","Andouille sausage","Rice","Onion","Bell peppers","Celery","Garlic"],"minor":["Smoked paprika","Oregano","Thyme","Garlic powder","Onion powder","Cayenne","Bay leaves","Parsley","Scallions"],"amounts":{"Dry red beans":"1 lb","Andouille sausage":"14 oz","Rice":"1.5 cups long grain white, uncooked","Onion":"1 yellow","Bell peppers":"1 green","Celery":"3 ribs","Garlic":"4 cloves"},"steps":[["Soak the dry beans in water overnight, then drain.",480],["Brown the sliced sausage in oil and set it aside.",null],["Cook onion, pepper, celery and garlic, then stir in spices and bay leaves.",null],["Add beans and fresh water, cover, and simmer.",60],["Mash some beans against the pot and simmer uncovered to thicken.",30],["Cook the rice separately while the beans finish.",null],["Return sausage with parsley, salt to taste, and serve over rice with green onions.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":702,"protein_g":33,"carbs_g":89,"fat_g":24},"video":"https://www.youtube.com/watch?v=awTM_rrfLKQ"}'::jsonb),
('jamaicanfoodsandrecipes-com-jamaican-rice-and-peas-recipe', 'Jamaican Rice and Peas Recipe', 'Caribbean', 'Jamaican Foods and Recipes', 'https://jamaicanfoodsandrecipes.com/jamaican-rice-and-peas-recipe/', 50, 3, 1, 1, 3, 5, 38, array['kidney beans', 'rice', 'coconut milk', 'onion', 'garlic']::text[], '{"title":"Jamaican Rice and Peas Recipe","cuisine":"Caribbean","source":"Jamaican Foods and Recipes","url":"https://jamaicanfoodsandrecipes.com/jamaican-rice-and-peas-recipe/","minutes":50,"servings":3,"key":["Dry kidney beans","Rice","Coconut milk","Onion","Garlic"],"minor":["Scallions","Thyme","Scotch bonnet pepper","Ginger","Allspice berries"],"amounts":{"Dry kidney beans":"100 g (or 1 can)","Rice":"263 g long grain","Coconut milk":"231 ml","Onion":"1/2 red","Garlic":"2 cloves"},"steps":[["Soak the dry beans at least two hours, or use a can of kidney beans instead.",120],["Pressure cook beans with garlic, allspice, ginger and salt.",20],["Add coconut milk, thyme, scallion, onion and the whole scotch bonnet; bring to a boil.",null],["Stir in rinsed rice, return to a boil, then drop heat to low and steam until liquid is gone.",20],["Rest a few minutes, then pull out thyme stems, pepper and ginger before serving.",3]],"technique":1,"prep":1,"precision":3,"nutrition":{"calories":264,"protein_g":5,"carbs_g":58,"fat_g":1},"video":null}'::jsonb),
('www-budgetbytes-com-picadillo', 'Authentic and Delicious Picadillo Recipe', 'Caribbean', 'Budget Bytes', 'https://www.budgetbytes.com/picadillo/', 30, 8, 2, 2, 1, 5, 38, array['beef', 'tomatoes', 'onion', 'bell peppers', 'green olive', 'raisin']::text[], '{"title":"Authentic and Delicious Picadillo Recipe","cuisine":"Caribbean","source":"Budget Bytes","url":"https://www.budgetbytes.com/picadillo/","minutes":30,"servings":8,"key":["Ground beef","Tomato sauce","Onion","Bell peppers","Green olives","Raisins"],"minor":["Garlic","Sazon","Adobo","Sofrito","White vinegar","Bay leaves"],"amounts":{"Ground beef":"1 lb (80/20)","Tomato sauce":"15 oz","Onion":"1 small yellow","Bell peppers":"1 red","Green olives":"1/2 cup sliced pimento-stuffed","Raisins":"1/4 cup"},"steps":[["Cook diced onion and red pepper in oil until soft, then add garlic.",null],["Add ground beef with salt, sazon and adobo and brown it well.",null],["Stir in the sofrito.",null],["Add olives, raisins, vinegar, tomato sauce, bay leaves and water.",null],["Simmer until the sauce thickens, then remove bay leaves.",10]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":212,"protein_g":11,"carbs_g":7,"fat_g":16},"video":null}'::jsonb),
('muybuenoblog-com-brazilian-feijoada', 'Brazilian Feijoada (Pork and Black Bean Stew)', 'Brazilian', 'Muy Bueno', 'https://muybuenoblog.com/brazilian-feijoada/', 255, 12, 4, 3, 2, 7, 81, array['black beans', 'bacon', 'pork', 'sausage', 'onion', 'tomatoes', 'rice']::text[], '{"title":"Brazilian Feijoada (Pork and Black Bean Stew)","cuisine":"Brazilian","source":"Muy Bueno","url":"https://muybuenoblog.com/brazilian-feijoada/","minutes":255,"servings":12,"key":["Dry black beans","Bacon","Pork chops","Smoked sausage","Onion","Tomatoes","Rice"],"minor":["Garlic","Bay leaves","Bell pepper","Cilantro","Butter","Chicken broth","Scallions"],"amounts":{"Dry black beans":"1 lb","Bacon":"1 lb","Pork chops":"4 thin","Smoked sausage":"14 oz","Onion":"1 large + 1/2","Tomatoes":"3","Rice":"1.5 cups white basmati"},"steps":[["Rinse the beans and cook with onion, garlic, bay leaves and salt until tender (stovetop or pressure cooker).",30],["Crisp the bacon in a Dutch oven and set it aside.",null],["Brown cubed pork in the drippings, then add sliced sausage.",8],["Soften onion and garlic, then add tomatoes, bell pepper and cilantro.",null],["Combine beans and their liquid with the meats, season, and simmer low until thick.",150],["Make garlic butter rice: toast rice in garlic and butter, add broth, and simmer.",16],["Serve the stew over the rice.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":381,"protein_g":11,"carbs_g":33,"fat_g":23},"video":null}'::jsonb),
('www-budgetbytes-com-chicken-enchiladas', 'Chicken Enchiladas', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-enchiladas/', 50, 4, 3, 2, 2, 6, 53, array['chicken', 'tortillas', 'enchilada sauce', 'cheddar', 'green chilie']::text[], '{"title":"Chicken Enchiladas","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/chicken-enchiladas/","minutes":50,"servings":4,"key":["Chicken","Flour tortillas","Enchilada sauce","Shredded Mexican cheese","Canned green chilies"],"minor":["Cumin","Garlic powder"],"amounts":{"Chicken":"3 cups cooked, shredded","Flour tortillas":"8","Enchilada sauce":"2 cups, divided","Shredded Mexican cheese":"2½ cups, divided","Canned green chilies":"4 oz can, diced"},"steps":[["Make or warm the enchilada sauce and shred the cooked chicken.",null],["Stir chicken with cumin, garlic powder, salt, green chilies and ¾ cup cheese.",null],["Heat oven to 350°F and warm tortillas so they roll without cracking.",null],["Spread ½ cup sauce in a 9x13 dish, fill tortillas, roll and lay seam-side down.",null],["Cover with the rest of the sauce and cheese.",null],["Bake at 350°F until the cheese melts and bubbles.",20]],"technique":3,"prep":2,"precision":2,"nutrition":{"calories":771,"protein_g":53,"carbs_g":60,"fat_g":34},"video":"https://www.youtube.com/watch?v=MO2Z1Zxz9UM"}'::jsonb),
('www-budgetbytes-com-2015-09-poor-mans-burrito-bowls', 'Poor Man''s Burrito Bowls', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/2015/09/poor-mans-burrito-bowls/', 25, 6, 1, 1, 1, 5, 27, array['rice', 'black beans', 'salsa', 'cheddar', 'scallions']::text[], '{"title":"Poor Man''s Burrito Bowls","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/2015/09/poor-mans-burrito-bowls/","minutes":25,"servings":6,"key":["Long grain white rice","Canned black beans","Salsa","Shredded cheese","Green onions"],"minor":["Ground cumin","Garlic powder","Jalapeño"],"amounts":{"Long grain white rice":"2 cups uncooked","Canned black beans":"2 (15 oz) cans","Salsa":"1 (16 oz) jar","Shredded cheese":"6 oz","Green onions":"1 bunch"},"steps":[["Bring rice, salt and water to a boil in a covered pot.",null],["Drop heat to low and simmer covered, then rest 5 minutes and fluff.",15],["Meanwhile warm undrained beans with cumin and garlic powder over medium, stirring often.",null],["Slice the green onions and jalapeño.",null],["Build bowls with rice, beans, salsa and cheese, then top with onions and jalapeño.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":522,"protein_g":20,"carbs_g":85,"fat_g":10},"video":null}'::jsonb),
('www-budgetbytes-com-baked-beef-black-bean-tacos', 'Crispy Baked Beef Tacos', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/baked-beef-black-bean-tacos/', 35, 5, 2, 2, 2, 6, 43, array['beef', 'black beans', 'taco shells', 'cheddar', 'onion', 'garlic']::text[], '{"title":"Crispy Baked Beef Tacos","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/baked-beef-black-bean-tacos/","minutes":35,"servings":5,"key":["Ground beef","Canned black beans","Hard taco shells","Cheddar","Onion","Garlic"],"minor":["Chili powder","Smoked paprika","Ground cumin","Dried oregano","Cayenne pepper","Tomato","Jalapeño","Cilantro","Sour cream"],"amounts":{"Ground beef":"½ lb lean","Canned black beans":"15 oz can","Hard taco shells":"1 box (10 shells)","Cheddar":"1 cup shredded (4 oz)","Onion":"1 yellow onion","Garlic":"2 cloves"},"steps":[["Stir the spices together for taco seasoning and heat the oven to 400°F.",null],["Soften diced onion and garlic in oil.",5],["Add beef and seasoning and cook until browned all the way through.",5],["Stir in the well-drained black beans.",null],["Stand shells upright in a baking dish, fill with beef mixture, and top with cheddar.",null],["Bake at 400°F until cheese melts and shell edges brown, then add toppings.",10]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":339,"protein_g":24,"carbs_g":26,"fat_g":16},"video":"https://www.youtube.com/watch?v=MU50rxvgCfA"}'::jsonb),
('www-recipetineats-com-spaghetti-bolognese', 'Spaghetti Bolognese', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/spaghetti-bolognese/', 40, 5, 4, 2, 2, 6, 56, array['beef', 'pasta', 'tomatoes', 'onion', 'garlic', 'red wine', 'tomato paste']::text[], '{"title":"Spaghetti Bolognese","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/spaghetti-bolognese/","minutes":40,"servings":5,"key":["Ground beef","Spaghetti","Canned crushed tomatoes","Onion","Garlic","Red wine","Tomato paste"],"minor":["Beef bouillon cubes","Worcestershire sauce","Bay leaves","Fresh thyme","Parmesan","Parsley"],"amounts":{"Ground beef":"1 lb (500g)","Spaghetti":"400g (13 oz)","Canned crushed tomatoes":"800g (28 oz) can","Onion":"1","Garlic":"2 cloves","Red wine":"½ cup (125 ml)","Tomato paste":"2 tbsp"},"steps":[["Soften onion and garlic in oil.",3],["Turn heat up and brown the beef, breaking it into small bits.",2],["Pour in wine and let it bubble until the alcohol smell fades.",1],["Add tomatoes, paste, bouillon, Worcestershire and herbs; simmer uncovered, stirring now and then.",25],["Cook spaghetti in salted water while the sauce simmers.",null],["Toss pasta with sauce briefly and finish with parmesan and parsley.",2]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":510,"protein_g":41,"carbs_g":53,"fat_g":13},"video":null}'::jsonb),
('www-recipetineats-com-aglio-e-olio-garlic-spaghetti', 'Aglio e Olio (Spaghetti with garlic olive oil)', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/', 18, 5, 4, 1, 3, 6, 50, array['pasta', 'garlic', 'oil', 'parmesan']::text[], '{"title":"Aglio e Olio (Spaghetti with garlic olive oil)","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/","minutes":18,"servings":5,"key":["Spaghetti","Garlic","Olive oil","Parmesan"],"minor":["Red chili flakes","Parsley"],"amounts":{"Spaghetti":"500g / 1 lb","Garlic":"6 large cloves, finely sliced","Olive oil":"½ cup extra virgin","Parmesan":"for serving"},"steps":[["Boil spaghetti in salted water for 1 minute less than the packet says.",11],["Save a cup of pasta water, then drain.",null],["Gently fry sliced garlic in olive oil over medium until pale golden, not brown.",3],["Add chili flakes for about 30 seconds.",null],["Add pasta, ½ cup reserved water and salt; toss over medium-high until glossy.",2],["Toss in parsley and serve right away with parmesan.",null]],"technique":4,"prep":1,"precision":3,"nutrition":{"calories":564,"protein_g":13,"carbs_g":75,"fat_g":23},"video":null}'::jsonb),
('www-recipetineats-com-lasagna', 'Lasagna!', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/lasagna/', 260, 10, 4, 4, 3, 8, 87, array['beef', 'lasagna sheets', 'tomatoes', 'milk', 'butter', 'flour', 'mozzarella']::text[], '{"title":"Lasagna!","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/lasagna/","minutes":260,"servings":10,"key":["Ground beef","Lasagna sheets","Canned crushed tomatoes","Milk","Butter","Flour","Mozzarella"],"minor":["Onion","Carrot","Celery","Garlic","Tomato paste","Red wine","Beef bouillon cubes","Bay leaves","Dried thyme","Dried oregano","Worcestershire sauce","Gruyere or cheddar","Nutmeg","Basil or parsley"],"amounts":{"Ground beef":"1 kg","Lasagna sheets":"350g fresh (or 250g dried)","Canned crushed tomatoes":"800g","Milk":"4 cups","Butter":"60g","Flour":"½ cup","Mozzarella":"1½ cups shredded"},"steps":[["Sauté onion, carrot, celery and garlic for the ragu base.",10],["Brown the beef, then add tomatoes, paste, wine, bouillon, herbs and Worcestershire.",null],["Simmer the ragu covered until the meat is very tender.",105],["Uncover and keep simmering until thick.",30],["For cheese sauce, cook butter and flour, whisk in milk until thick, then stir in cheese and nutmeg.",8],["Layer ragu, pasta sheets and cheese sauce three times, finishing with sauce and mozzarella.",null],["Bake at 350°F (180°C) until golden and bubbling.",25],["Rest before cutting.",10]],"technique":4,"prep":4,"precision":3,"nutrition":{"calories":594,"protein_g":39,"carbs_g":40,"fat_g":29},"video":null}'::jsonb),
