('thewoksoflife-com-stir-fried-tomato-and-egg', 'Chinese Tomato Egg Stir-fry (番茄炒鸡蛋)', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/stir-fried-tomato-and-egg/', 10, 2, 2, 1, 1, 6, 32, array['eggs', 'tomatoes', 'scallions']::text[], '{"title":"Chinese Tomato Egg Stir-fry (番茄炒鸡蛋)","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/stir-fried-tomato-and-egg/","minutes":10,"servings":2,"key":["Eggs","Tomatoes","Scallions"],"minor":["White pepper","Sesame oil","Shaoxing wine"],"amounts":{"Eggs":"4","Tomatoes":"4 small to medium (about 1 lb)","Scallions":"1"},"steps":[["Cut tomatoes into wedges, discarding stems, and finely chop the scallion.",null],["Whisk eggs with a little salt, white pepper, sesame oil and Shaoxing wine.",null],["Scramble eggs in 2 tbsp oil in a smoking-hot wok over medium heat, then set them aside.",null],["Add remaining oil, turn heat to high and stir-fry tomatoes and scallion for a minute.",1],["Add sugar, salt and water, return the eggs, cover and cook until tomatoes fully soften.",2],["Uncover and stir-fry on high until the sauce thickens to your liking; serve over rice.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":333,"protein_g":11,"carbs_g":6,"fat_g":30},"video":null}'::jsonb),
('thewoksoflife-com-kung-pao-chicken', 'Kung Pao Chicken: An Authentic Chinese Recipe', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/kung-pao-chicken/', 40, 4, 3, 3, 3, 7, 57, array['chicken', 'peanuts', 'scallions', 'garlic', 'soy sauce']::text[], '{"title":"Kung Pao Chicken: An Authentic Chinese Recipe","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/kung-pao-chicken/","minutes":40,"servings":4,"key":["Chicken breast","Peanuts","Scallions","Garlic","Soy sauce"],"minor":["Ginger","Dried red chilies","Sichuan peppercorn powder","Shaoxing wine","Dark soy sauce","Rice vinegar","Cornstarch","White pepper"],"amounts":{"Chicken breast":"12 oz","Peanuts":"1 cup raw, shelled","Scallions":"6 (white parts)","Garlic":"3 cloves","Soy sauce":"1 tbsp light soy sauce"},"steps":[["Toast peanuts in a teaspoon of oil over medium heat, stirring constantly, then let them cool.",3],["Toss cubed chicken with oil, cornstarch, Shaoxing wine, salt and white pepper; let it marinate.",20],["Stir together soy sauces, vinegar, sugar, water and cornstarch for the sauce.",null],["Sear chicken in 2 tbsp oil over high heat, then move it to a bowl.",null],["On low heat, cook garlic, ginger, chilies, peppercorn powder and scallions until fragrant.",2],["Return chicken, raise heat to high and stir-fry briefly.",1],["Stir the sauce, pour it in and cook until glossy and thick, then toss in the peanuts.",1]],"technique":3,"prep":3,"precision":3,"nutrition":{"calories":440,"protein_g":29,"carbs_g":11,"fat_g":33},"video":null}'::jsonb),
('thewoksoflife-com-ma-po-tofu-real-deal', 'Mapo Tofu Recipe: The Real Deal', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/ma-po-tofu-real-deal/', 35, 6, 4, 3, 4, 7, 64, array['tofu', 'pork', 'garlic', 'ginger', 'broth', 'scallions']::text[], '{"title":"Mapo Tofu Recipe: The Real Deal","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/ma-po-tofu-real-deal/","minutes":35,"servings":6,"key":["Silken tofu","Ground pork","Garlic","Ginger","Chicken broth","Scallions"],"minor":["Thai bird chilies","Dried red chilies","Sichuan peppercorns","Spicy bean sauce (doubanjiang)","Cornstarch","Sesame oil"],"amounts":{"Silken tofu":"1 lb","Ground pork":"8 oz","Garlic":"3 tbsp minced","Ginger":"3 tbsp minced","Chicken broth":"2/3 cup low-sodium","Scallions":"1"},"steps":[["Gently heat fresh and dried chilies in 1/4 cup oil to make a chili oil; set aside.",5],["In the remaining oil, cook ginger for a minute, then add garlic.",1],["Turn heat to high and brown the pork, breaking it up until fully cooked.",null],["Stir in ground Sichuan peppercorns briefly without letting them scorch.",null],["Add bean sauce and broth, simmer a minute, then thicken with cornstarch slurry.",1],["Fold in the chili oil and tofu, tossing gently until heated through.",4],["Finish with sesame oil, sugar and scallions, then dust with more peppercorn powder.",null]],"technique":4,"prep":3,"precision":4,"nutrition":{"calories":335,"protein_g":11,"carbs_g":8,"fat_g":29},"video":null}'::jsonb),
('www-justonecookbook-com-oyakodon', 'Oyakodon (Chicken and Egg Rice Bowl) 親子丼', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/oyakodon/', 25, 2, 2, 2, 3, 6, 42, array['chicken', 'eggs', 'onion', 'rice', 'soy sauce', 'scallions']::text[], '{"title":"Oyakodon (Chicken and Egg Rice Bowl) 親子丼","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/oyakodon/","minutes":25,"servings":2,"key":["Chicken thighs","Eggs","Onion","Rice","Soy sauce","Scallions"],"minor":["Dashi","Mirin","Sake","Shichimi togarashi","Sansho pepper"],"amounts":{"Chicken thighs":"10 oz boneless, skinless","Eggs":"3-4 large","Onion":"1/2 yellow onion (4 oz)","Rice":"2 servings cooked short-grain","Soy sauce":"2 Tbsp","Scallions":"4 sprigs (or mitsuba)"},"steps":[["Stir together dashi, soy sauce, mirin and sugar for the simmering sauce.",null],["Slice onion into strips, chop the greens, cut chicken into bite-size pieces and toss with sake.",null],["Loosely break up eggs with chopsticks, leaving streaks of white.",null],["Simmer onion in the sauce, add chicken and cook uncovered, flipping halfway.",5],["Pour in two-thirds of the egg around the center and cook until just set.",null],["Add the rest of the egg and greens, cook to your liking and slide over rice with sauce.",null]],"technique":2,"prep":2,"precision":3,"nutrition":{"calories":537,"protein_g":42,"carbs_g":50,"fat_g":13},"video":"https://www.youtube.com/watch?v=SgIMT1L7kXM"}'::jsonb),
('www-justonecookbook-com-tonkatsu', 'Tonkatsu (Japanese Pork Cutlet)', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/tonkatsu/', 30, 2, 4, 3, 4, 7, 63, array['pork', 'panko breadcrumb', 'eggs', 'flour', 'cabbage']::text[], '{"title":"Tonkatsu (Japanese Pork Cutlet)","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/tonkatsu/","minutes":30,"servings":2,"key":["Pork loin chops","Panko breadcrumbs","Eggs","Flour","Cabbage"],"minor":["Tonkatsu sauce","Sesame seeds","Japanese cucumber"],"amounts":{"Pork loin chops":"2 boneless, 1/2 inch thick (100 g each)","Panko breadcrumbs":"1/2 cup","Eggs":"1 large","Flour":"2 Tbsp all-purpose","Cabbage":"1/4 head green cabbage"},"steps":[["Grind sesame seeds and mix into bowls of tonkatsu sauce for dipping.",null],["Trim fat, nick the connective tissue, pound the pork and season with salt and pepper.",null],["Heat 3 cups oil in a deep pot to 340°F (170°C).",null],["Coat cutlets in flour, then egg mixed with oil, then panko; rest them.",5],["Fry each cutlet about a minute per side, then drain on a rack.",4],["Raise oil to 355°F (180°C) and refry briefly per side; pork should reach 145°F.",1],["Rest, slice into strips and serve with shredded cabbage and sauce.",2]],"technique":4,"prep":3,"precision":4,"nutrition":{"calories":523,"protein_g":27,"carbs_g":15,"fat_g":37},"video":"https://www.youtube.com/watch?v=OlEEEiHlGn4"}'::jsonb),
