('www-recipetineats-com-butter-chicken', 'Butter Chicken (Murgh Makhani)', 'Indian', 'RecipeTin Eats', 'https://www.recipetineats.com/butter-chicken/', 35, 4, 4, 2, 2, 4, 51, array['chicken', 'yogurt', 'tomatoes', 'cream', 'butter', 'garlic', 'ginger']::text[], '{"title":"Butter Chicken (Murgh Makhani)","cuisine":"Indian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/butter-chicken/","minutes":35,"servings":4,"key":["Chicken thighs","Yogurt","Tomato passata","Heavy cream","Butter","Garlic","Ginger"],"minor":["Lemon juice","Turmeric","Garam masala","Chili powder","Ground cumin","Cilantro","Basmati rice (to serve)"],"amounts":{"Chicken thighs":"1.5 lb (750g), bite-sized","Yogurt":"1/2 cup plain full fat","Tomato passata":"1 cup","Heavy cream":"1 cup","Butter":"2 tbsp ghee or butter","Garlic":"2 cloves, crushed","Ginger":"1 tbsp fresh grated"},"steps":[["Stir yogurt, lemon, ginger, garlic and spices together, coat the chicken and chill at least 3 hours.",180],["Melt ghee in a large pan over high heat and cook the chicken until the outside turns white.",3],["Add passata, cream, sugar, salt and any leftover marinade, then simmer on low until thick.",20],["Taste for salt, scatter cilantro and serve over basmati rice.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":402,"protein_g":40,"carbs_g":10,"fat_g":23},"video":null}'::jsonb),
('www-indianhealthyrecipes-com-dal-tadka', 'Dal Tadka Recipe (Restaurant Style)', 'Indian', 'Swasthi''s Recipes', 'https://www.indianhealthyrecipes.com/dal-tadka/', 40, 4, 2, 2, 2, 6, 44, array['lentils', 'onion', 'tomatoes', 'garlic', 'ginger', 'butter', 'lemon']::text[], '{"title":"Dal Tadka Recipe (Restaurant Style)","cuisine":"Indian","source":"Swasthi''s Recipes","url":"https://www.indianhealthyrecipes.com/dal-tadka/","minutes":40,"servings":4,"key":["Lentils","Onion","Tomatoes","Garlic","Ginger","Ghee","Lemon"],"minor":["Cumin seeds","Green chili","Turmeric","Red chili powder","Garam masala","Kasuri methi","Coriander leaves","Dried red chilies","Asafoetida","Mustard seeds","Curry leaves"],"amounts":{"Lentils":"1 cup (200g) mixed toor, moong and chana dal","Onion":"1/3 to 1/2 cup chopped","Tomatoes":"2 medium, deseeded and chopped","Garlic":"1 tsp chopped, plus 1/2 to 1 tbsp for tadka","Ginger":"1 tsp chopped","Ghee":"2 tbsp","Lemon":"1 medium"},"steps":[["Rinse the dal well and pressure cook with 3 cups water for 3 to 4 whistles until soft.",15],["Fry cumin in oil, then garlic, ginger, onion and green chili until the onion softens.",5],["Add turmeric, chili powder, garam masala, tomatoes and salt; cook until tomatoes break down.",5],["Stir in the cooked dal and simmer, then add kasuri methi and coriander.",7],["For the tadka, heat ghee and fry cumin, mustard seeds, dried chilies, garlic, asafoetida and chili powder.",2],["Pour the sizzling tadka over the dal and serve with a squeeze of lemon.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":351,"protein_g":16,"carbs_g":43,"fat_g":14},"video":"https://www.youtube.com/watch?v=63_KsWxTOyk"}'::jsonb),
('www-cookwithmanali-com-chana-masala', 'Chana Masala (using raw chickpeas)', 'Indian', 'Cook With Manali', 'https://www.cookwithmanali.com/chana-masala/', 60, 3, 4, 2, 2, 7, 63, array['chickpeas', 'onion', 'tomatoes', 'tomato paste', 'garlic', 'ginger']::text[], '{"title":"Chana Masala (using raw chickpeas)","cuisine":"Indian","source":"Cook With Manali","url":"https://www.cookwithmanali.com/chana-masala/","minutes":60,"servings":3,"key":["Chickpeas","Onion","Tomatoes","Tomato paste","Garlic","Ginger"],"minor":["Green chili","Bay leaf","Green cardamom","Cloves","Cinnamon stick","Black peppercorns","Cumin seeds","Coriander powder","Cumin powder","Paprika","Turmeric","Garam masala","Kasuri methi","Cilantro"],"amounts":{"Chickpeas":"1 cup raw (200g), soaked overnight, or 2.5 cups canned","Onion":"1 large red onion, finely chopped","Tomatoes":"2 medium, pureed","Tomato paste":"1 tbsp","Garlic":"3-4 large cloves","Ginger":"1 inch"},"steps":[["Soak chickpeas overnight, then pressure cook with salt and water until tender (skip if using canned).",null],["Crush ginger, garlic and green chili into a rough paste.",null],["Toast the whole spices in hot oil until fragrant, then soften the onion with a pinch of salt.",8],["Add the ginger-garlic paste and cook until the raw smell is gone.",2],["Stir in pureed tomato and tomato paste and simmer.",5],["Add ground spices for 30 seconds, then the chickpeas and water; simmer on medium-low.",15],["Finish with crushed kasuri methi and cilantro and serve hot.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":234,"protein_g":7,"carbs_g":29,"fat_g":11},"video":null}'::jsonb),
('www-themediterraneandish-com-shakshuka-recipe', 'Shakshuka Recipe (Easy and Authentic)', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/shakshuka-recipe/', 40, 6, 2, 2, 2, 5, 42, array['eggs', 'tomatoes', 'onion', 'bell peppers', 'garlic']::text[], '{"title":"Shakshuka Recipe (Easy and Authentic)","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/shakshuka-recipe/","minutes":40,"servings":6,"key":["Eggs","Tomatoes","Onion","Green bell peppers","Garlic","Tomato sauce"],"minor":["Ground coriander","Sweet paprika","Ground cumin","Red pepper flakes","Parsley","Mint","Olive oil"],"amounts":{"Eggs":"6 large","Tomatoes":"6 medium, chopped (about 6 cups)","Onion":"1 large yellow onion, chopped","Green bell peppers":"2, chopped","Garlic":"2 cloves, chopped","Tomato sauce":"1/2 cup"},"steps":[["Sauté onion, peppers, garlic and spices in olive oil until softened.",5],["Add chopped tomatoes and tomato sauce, cover and simmer, then uncover to thicken.",15],["Make six wells in the sauce and crack an egg into each.",null],["Cover and cook over medium-low until the whites are set.",8],["Top with parsley and mint and serve with bread.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":173,"protein_g":8,"carbs_g":11,"fat_g":12},"video":null}'::jsonb),
('www-themediterraneandish-com-chicken-shawarma-recipe', 'Chicken Shawarma', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/chicken-shawarma-recipe/', 40, 6, 3, 2, 2, 6, 50, array['chicken', 'onion', 'lemon', 'pita', 'arugula']::text[], '{"title":"Chicken Shawarma","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/chicken-shawarma-recipe/","minutes":40,"servings":6,"key":["Chicken thighs","Onion","Lemon","Pita bread","Arugula"],"minor":["Ground cumin","Turmeric","Ground coriander","Garlic powder","Paprika","Ground cloves","Cayenne","Olive oil","Tahini or tzatziki","Pickles or kalamata olives"],"amounts":{"Chicken thighs":"8 boneless, skinless","Onion":"1 large, thinly sliced","Lemon":"juice of 1 large","Pita bread":"6 pita pockets","Arugula":"baby arugula, to serve"},"steps":[["Mix the shawarma spice blend in a small bowl.",null],["Pat chicken dry, salt it and cut into bite-size pieces.",null],["Toss chicken with spices, onion, lemon juice and olive oil; marinate up to 3 hours or overnight if time allows.",null],["Heat oven to 425°F and spread chicken and onions in one layer on an oiled sheet pan.",null],["Roast until the chicken reaches 165°F internally; broil briefly for crisp edges if you like.",30],["Fill pitas with sauce, chicken, arugula, salad and pickles and serve right away.",null]],"technique":3,"prep":2,"precision":2,"nutrition":{"calories":467,"protein_g":35,"carbs_g":37,"fat_g":20},"video":null}'::jsonb),
('www-themediterraneandish-com-mujadara', 'Authentic Mujadara (Middle Eastern Lentils, Rice and Onions)', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/mujadara/', 120, 6, 2, 2, 3, 6, 66, array['lentils', 'rice', 'onion']::text[], '{"title":"Authentic Mujadara (Middle Eastern Lentils, Rice and Onions)","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/mujadara/","minutes":120,"servings":6,"key":["Lentils","Rice","Onion"],"minor":["Cumin","Parsley","Olive oil","Black pepper"],"amounts":{"Lentils":"1 cup black lentils, rinsed","Rice":"1 cup long-grain white rice, soaked and drained","Onion":"2 large diced (4 cups), plus 1 large thinly sliced for garnish"},"steps":[["Par-cook the lentils in 2 cups water, then drain.",12],["Slowly caramelize the diced onions in olive oil over medium-high heat until deep brown.",40],["Add 2 cups water to the onions, then stir in the rice, lentils, salt, pepper and cumin.",null],["Cover and cook on low until the liquid is absorbed.",20],["Meanwhile fry the sliced onion in olive oil until crisp and golden.",null],["Rest the pot, then top with crispy onions and parsley.",10]],"technique":2,"prep":2,"precision":3,"nutrition":{"calories":378,"protein_g":11,"carbs_g":47,"fat_g":17},"video":null}'::jsonb),
('www-chilipeppermadness-com-recipes-misir-wat', 'Misir Wat Recipe (Ethiopian Spicy Red Lentils)', 'Ethiopian', 'Chili Pepper Madness', 'https://www.chilipeppermadness.com/recipes/misir-wat/', 45, 4, 2, 1, 2, 5, 40, array['lentils', 'onion', 'garlic', 'ginger', 'tomato paste', 'broth']::text[], '{"title":"Misir Wat Recipe (Ethiopian Spicy Red Lentils)","cuisine":"Ethiopian","source":"Chili Pepper Madness","url":"https://www.chilipeppermadness.com/recipes/misir-wat/","minutes":45,"servings":4,"key":["Red lentils","Onion","Garlic","Ginger","Tomato paste","Broth"],"minor":["Berbere spice","Black pepper","Nigella seeds","Cardamom","Cilantro","Niter kibbeh (optional)"],"amounts":{"Red lentils":"1 cup dry, rinsed","Onion":"2 medium, chopped","Garlic":"4 cloves, minced","Ginger":"1 tsp minced","Tomato paste":"3 tbsp","Broth":"3 cups chicken or vegetable"},"steps":[["Soften the onions in oil or niter kibbeh in a large pan.",5],["Add garlic and ginger and cook briefly.",1],["Stir in tomato paste, berbere, black pepper, nigella and cardamom and toast for a minute.",1],["Add lentils, broth and salt, bring to a boil, then cover and simmer until lentils are tender.",35],["Rest for extra flavor if you have time, then garnish with cilantro.",null]],"technique":2,"prep":1,"precision":2,"nutrition":null,"video":null}'::jsonb),
('www-chilipeppermadness-com-recipes-doro-wat', 'Doro Wat Recipe (Ethiopian Chicken Stew)', 'Ethiopian', 'Chili Pepper Madness', 'https://www.chilipeppermadness.com/recipes/doro-wat/', 115, 4, 4, 3, 3, 7, 82, array['chicken', 'onion', 'eggs', 'tomato paste', 'garlic', 'ginger', 'lemon']::text[], '{"title":"Doro Wat Recipe (Ethiopian Chicken Stew)","cuisine":"Ethiopian","source":"Chili Pepper Madness","url":"https://www.chilipeppermadness.com/recipes/doro-wat/","minutes":115,"servings":4,"key":["Chicken thighs","Red onions","Eggs","Tomato paste","Garlic","Ginger","Lemon"],"minor":["Berbere seasoning","Paprika","Niter kibbeh or ghee","Chicken stock","Parsley","Canola oil"],"amounts":{"Chicken thighs":"2 lbs thighs and legs, skin removed","Red onions":"2 large, chopped","Eggs":"4-6 large, hard-boiled and peeled","Tomato paste":"2 tbsp","Garlic":"6 cloves, chopped","Ginger":"1 tbsp minced","Lemon":"juice of 1"},"steps":[["Soak the chicken in lemon water, then drain and rinse.",30],["Cook the chopped onions in a dry pot, stirring, until soft and caramelized.",20],["Add oil, garlic, ginger, berbere, paprika, salt and pepper and cook until fragrant.",3],["Stir in tomato paste and cook to deepen the color.",5],["Pour in water or stock, bring to a boil, add the chicken and simmer on low.",40],["Stir in niter kibbeh and the peeled eggs and simmer a little longer.",10],["Serve with injera or rice, plus parsley and lemon.",null]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":434,"protein_g":34,"carbs_g":11,"fat_g":27},"video":null}'::jsonb),
('www-recipetineats-com-shepherds-pie', 'Shepherd''s Pie', 'British', 'RecipeTin Eats', 'https://www.recipetineats.com/shepherds-pie/', 80, 6, 4, 3, 2, 7, 71, array['lamb', 'potatoes', 'onion', 'carrots', 'peas', 'broth', 'butter']::text[], '{"title":"Shepherd''s Pie","cuisine":"British","source":"RecipeTin Eats","url":"https://www.recipetineats.com/shepherds-pie/","minutes":80,"servings":6,"key":["Ground lamb","Potatoes","Onion","Carrots","Frozen peas","Beef stock","Butter"],"minor":["Garlic","Celery","Dried thyme","Dried rosemary","Flour","Tomato paste","Red wine","Beef bouillon cube","Worcestershire sauce","Bay leaves","Milk","Parmesan","Olive oil"],"amounts":{"Ground lamb":"750g ground lamb or beef","Potatoes":"1.2kg, peeled and cubed","Onion":"1, finely chopped","Carrots":"1, finely chopped","Frozen peas":"1 cup","Beef stock":"2 cups","Butter":"2 tbsp for mash, plus 2 tbsp melted for topping"},"steps":[["Sauté onion, garlic, carrot, celery and dried herbs in oil until soft.",5],["Turn heat to high and brown the ground lamb.",5],["Add flour, tomato paste, stock, wine, bouillon, Worcestershire and bay leaves; simmer until thick.",30],["Season, move to a baking dish, stir in peas and let it cool so the mash sits on top.",null],["Boil potatoes until soft, then mash with butter and milk.",15],["Spread the mash over the filling, rough it up with a fork, add parmesan and melted butter.",null],["Bake at 180°C until golden on top.",35]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":653,"protein_g":31,"carbs_g":14,"fat_g":50},"video":null}'::jsonb),
('www-recipetineats-com-toad-in-the-hole', 'Toad in the Hole', 'British', 'RecipeTin Eats', 'https://www.recipetineats.com/toad-in-the-hole/', 55, 4, 5, 2, 4, 6, 70, array['sausage', 'eggs', 'flour', 'milk', 'onion', 'broth']::text[], '{"title":"Toad in the Hole","cuisine":"British","source":"RecipeTin Eats","url":"https://www.recipetineats.com/toad-in-the-hole/","minutes":55,"servings":4,"key":["Pork sausages","Eggs","Flour","Milk","Onion","Beef stock"],"minor":["Beef drippings or canola oil","Mayonnaise","White pepper","Garlic","Worcestershire sauce","Butter","Black pepper"],"amounts":{"Pork sausages":"700g (8 x 85g)","Eggs":"250ml whisked (4-5 large)","Flour":"1 cup plain flour, plus 3 tbsp for gravy","Milk":"3/4 cup full-fat","Onion":"2, cut into wedges","Beef stock":"2 cups low-sodium"},"steps":[["Whisk eggs, flour, milk, water, mayo, salt and pepper into a batter and chill it.",null],["Heat oven to 220°C and heat the drippings in the baking pan until smoking hot.",15],["Brown the sausages on the stovetop, leaving one side lightly colored.",5],["Pour the cold batter around the sausages in the hot pan and bake on the top shelf until puffed and golden; do not open the oven.",25],["For gravy, cook onion wedges until deep brown, add garlic and flour, then whisk in stock and Worcestershire.",10],["Simmer gravy until thick and serve straight away with the toad in the hole.",3]],"technique":5,"prep":2,"precision":4,"nutrition":{"calories":1017,"protein_g":41,"carbs_g":36,"fat_g":78},"video":null}'::jsonb)
